package hu.synostream.android;
import android.content.*;import android.widget.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.util.*;
@RunWith(AndroidJUnit4.class) public class Android0512Test {
 final Android050FlowTest f=new Android050FlowTest();
 @Before public void init(){f.instrumentation=InstrumentationRegistry.getInstrumentation();f.context=f.instrumentation.getTargetContext();f.app=(SynoApp)f.context.getApplicationContext();f.device=UiDevice.getInstance(f.instrumentation);UiLocale.save(f.context,"hu");}
 @After public void cleanup()throws Exception{UiLocale.save(f.context,"hu");f.instrumentation.runOnMainSync(()->{f.app.cancelScan();f.app.epoch++;f.app.torrentDraft.close();f.app.externalTorrentUri=null;f.app.externalTorrentMime=null;});f.cleanup();}
 void login()throws Exception{f.device.wakeUp();f.device.executeShellCommand("wm dismiss-keyguard");f.device.setOrientationNatural();f.instrumentation.runOnMainSync(()->{f.app.client=null;f.app.demo=false;f.app.busy=false;f.app.page="movies";f.app.libraryDraft=null;f.app.downloadsOpen=false;});f.context.startActivity(new Intent(f.context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/login_address_help")),10000));f.instrumentation.waitForIdleSync();}
 void label(String id,String value){assertTrue(id+" must show the active connection mode",f.device.wait(Until.hasObject(By.res(f.pkg+":id/"+id).text(value)),10000));}
 @Test public void hungarianAddressHelpExplainsWebAddressesAndLocalExample()throws Exception{login();f.click("login_address_help");assertTrue(f.device.wait(Until.hasObject(By.res("android:id/message")),5000));assertTrue(f.device.takeScreenshot(new java.io.File(f.context.getFilesDir(),"0512-help-hu.png")));String text=f.device.findObject(By.res("android:id/message")).getText();assertTrue(text.contains("https://192.168.1.10:5001"));assertTrue(text.contains("http://192.168.1.10:5000"));assertTrue(text.contains("IP-cím önmagában HTTPS-ként"));assertTrue(text.contains("Windows-fájlmegosztási cím nem használható"));f.device.findObject(By.res("android:id/button1")).click();f.text(UiText.context(f.context).getString(R.string.connection_more));assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/login_local")),5000));MainActivity a=f.activity();f.instrumentation.runOnMainSync(()->assertEquals("Pl. http://192.168.1.10:5000",((EditText)a.findViewById(R.id.login_local)).getHint().toString()));}
 @Test public void englishAddressHelpIsLocalisedWithoutChangingInputDraft()throws Exception{UiLocale.save(f.context,"en");login();f.device.findObject(By.res(f.pkg+":id/login_address")).setText("fixture-quickconnect");f.click("login_address_help");assertTrue(f.device.wait(Until.hasObject(By.text("Entering the NAS address")),5000));
assertTrue("English help body must be visible",f.device.wait(Until.hasObject(By.res("android:id/message")),5000));String text=f.device.findObject(By.res("android:id/message")).getText();assertTrue(text.contains("An IP address alone is treated as HTTPS"));assertTrue(text.contains("Windows file-sharing addresses are not supported"));f.device.findObject(By.res("android:id/button1")).click();MainActivity activity=f.activity();f.instrumentation.runOnMainSync(()->assertEquals("fixture-quickconnect",((EditText)activity.findViewById(R.id.login_address)).getText().toString()));}
 @Test public void successfulRouteRemainsVisibleDuringWorkAndAcrossScreensAndLanguage()throws Exception{try(FakeNas nas=new FakeNas()){f.setup(nas,List.of(new Library.Card("/Movies/Fixture.mkv","Fixture",true)));f.app.store.put("address","fixture-quickconnect");label("connection_toolbar","Kapcsolat: Helyi hálózat");assertTrue(f.device.takeScreenshot(new java.io.File(f.context.getFilesDir(),"0512-route-hu.png")));f.instrumentation.runOnMainSync(()->{f.app.busy=true;f.app.status="Korábbi lista betöltése…";f.app.changed();});label("connection_toolbar","Kapcsolat: Helyi hálózat");f.instrumentation.runOnMainSync(()->{f.app.busy=false;f.app.status="";f.app.client.route="Helyi kapcsolat";f.app.changed();});label("connection_toolbar","Kapcsolat: Helyi hálózat");f.instrumentation.runOnMainSync(()->{f.app.client.route="QuickConnect";f.app.changed();});label("connection_toolbar","Kapcsolat: QuickConnect");f.click("menu_button");label("connection_drawer","Kapcsolat: QuickConnect");f.text("Beállítások");label("connection_settings","Kapcsolat: QuickConnect");f.device.setOrientationLeft();label("connection_toolbar","Kapcsolat: QuickConnect");label("connection_settings","Kapcsolat: QuickConnect");f.click("menu_button");label("connection_drawer","Kapcsolat: QuickConnect");assertTrue("Library must remain visible in the landscape drawer",f.device.wait(Until.hasObject(By.desc("Filmek médiatár")),5000));assertTrue("Landscape library label must have readable height",f.device.findObject(By.desc("Filmek médiatár")).getVisibleBounds().height()>=f.activity().dp(40));f.click("menu_button");UiLocale.save(f.context,"en");MainActivity a=f.activity();f.instrumentation.runOnMainSync(a::recreate);label("connection_toolbar","Connection: QuickConnect");label("connection_settings","Connection: QuickConnect");assertTrue(f.device.takeScreenshot(new java.io.File(f.context.getFilesDir(),"0512-route-en-landscape.png")));}}
}
